def fix_spaces(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == ' ':
            if len(text[i:]) > 2:
                result.append('-')
                i += 1
                while i < len(text) and text[i] == ' ':
                    i += 1
            else:
                result.append('_')
                i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result) 
