    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
      if n <= 1:
        return False
      for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
          return False
      return True
    count = 0
    for i in range(2, int(a**0.5) + 1):
      if is_prime(i):
        for j in range(i, int(a**0.5) + 1):
          if is_prime(j):
            for k in range(j, int(a**0.5) + 1):
              if is_prime(k) and i * j * k == a:
                count += 1
    return count >= 1 
